  bool Verify(::flatbuffers::VerifierTemplate<B> &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<uint32_t>(verifier, VT_FIRST_STEP, 4) &&
           VerifyField<uint32_t>(verifier, VT_STEP_COUNT, 4) &&
           VerifyField<int32_t>(verifier, VT_LAST_STEP, 4) &&
           VerifyField<uint32_t>(verifier, VT_OBJECTS, 4) &&
           VerifyOffset(verifier, VT_EXCLUDED) &&
           verifier.VerifyVector(EXCLUDED()) &&
           verifier.VerifyVectorOfTables(EXCLUDED()) &&
           VerifyField<uint32_t>(verifier, VT_PRIMARIES, 4) &&
           VerifyField<uint32_t>(verifier, VT_SECONDARIES, 4) &&
           VerifyField<uint32_t>(verifier, VT_SKIPPED, 4) &&
           VerifyField<uint32_t>(verifier, VT_CANDIDATE_COUNT, 4) &&
           verifier.EndTable();
  }
